<!DOCTYPE html>
<html lang="id">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Executive Project Monitor</title>
    <link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css">
    <script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.9/dist/chart.umd.min.js"></script>
    <script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
    <style>
        *{box-sizing:border-box}body{margin:0;background:#070b14;color:#f8fafc;font-family:Inter,ui-sans-serif,system-ui,sans-serif}.wrap{max-width:1600px;margin:auto;padding:30px}.header{margin-bottom:24px}.eyebrow{font-size:11px;letter-spacing:.2em;color:#38bdf8;font-weight:800;text-transform:uppercase}.title{font-size:34px;font-weight:850;margin:5px 0}.muted{color:#94a3b8}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:18px}.kpi,.card{background:#0d1320;border:1px solid #1e293b;border-radius:18px}.kpi{padding:20px}.kpi-label{font-size:12px;color:#94a3b8}.kpi-value{font-size:32px;font-weight:850;margin-top:8px}.layout-main{display:grid;grid-template-columns:minmax(0,1fr) 360px;gap:18px;align-items:stretch}.card{padding:20px}.card h2{font-size:16px;margin:0 0 18px}.project-card{min-width:0}.projects{display:grid;grid-template-columns:1fr 1fr;gap:16px}.project{position:relative;isolation:isolate;overflow:hidden;min-width:0;min-height:205px;padding:22px;border:1px solid rgba(148,163,184,.2);border-radius:22px;background:linear-gradient(135deg,#17243b 0%,#0b1425 52%,#111d33 100%);box-shadow:0 16px 35px rgba(0,0,0,.25)}.project::before{content:"";position:absolute;z-index:-1;width:220px;height:220px;right:-85px;top:-105px;border-radius:50%;background:radial-gradient(circle,rgba(56,189,248,.2),rgba(56,189,248,0) 68%)}.project::after{content:"";position:absolute;z-index:-1;width:260px;height:260px;right:-125px;bottom:-170px;border:1px solid rgba(255,255,255,.07);border-radius:50%;box-shadow:0 0 0 24px rgba(255,255,255,.018),0 0 0 48px rgba(255,255,255,.012)}.project:hover{transform:translateY(-2px);border-color:rgba(56,189,248,.42);box-shadow:0 20px 42px rgba(0,0,0,.32);transition:.2s ease}.project-top{display:flex;align-items:flex-start;justify-content:space-between;gap:14px;position:relative;z-index:1}.project-label{font-size:9px;letter-spacing:.18em;text-transform:uppercase;color:#7dd3fc;font-weight:800;margin-bottom:7px}.pname{font-size:18px;line-height:1.2;font-weight:850;max-width:80%}.client{font-size:11px;color:#94a3b8;margin-top:5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:90%}.badge{font-size:9px;padding:6px 9px;border-radius:999px;background:rgba(15,23,42,.78);border:1px solid rgba(125,211,252,.25);color:#bae6fd;height:max-content;white-space:nowrap}.chip{width:38px;height:28px;border-radius:7px;margin-top:24px;background:linear-gradient(135deg,#d9b66f,#f4d58a 48%,#b88c43);box-shadow:inset 0 0 0 1px rgba(255,255,255,.3),0 4px 10px rgba(0,0,0,.18);position:relative}.chip::before,.chip::after{content:"";position:absolute;left:9px;right:9px;height:1px;background:rgba(83,58,16,.42)}.chip::before{top:9px}.chip::after{bottom:9px}.project-middle{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-top:18px}.project-id{font-size:10px;letter-spacing:.16em;color:#64748b;text-transform:uppercase}.project-id strong{color:#cbd5e1;font-weight:700}.project-progress{min-width:130px}.progress-label{display:flex;justify-content:space-between;font-size:10px;color:#94a3b8;margin-bottom:6px}.progress{height:6px;background:rgba(15,23,42,.85);border-radius:99px;overflow:hidden}.bar{height:100%;background:linear-gradient(90deg,#38bdf8,#67e8f9);border-radius:99px;transition:width .4s}.project-bottom{display:flex;justify-content:space-between;align-items:flex-end;gap:12px;margin-top:18px;padding-top:12px;border-top:1px solid rgba(148,163,184,.12)}.project-bottom-label{font-size:8px;letter-spacing:.13em;color:#64748b;text-transform:uppercase}.project-bottom-value{font-size:11px;color:#e2e8f0;margin-top:3px;font-weight:700}.map-card{min-width:0}.map-wrap{height:100%;min-height:330px;border-radius:14px;overflow:hidden;border:1px solid #1e293b}.map{width:100%;height:100%;background:#0a101b}.leaflet-container{font-family:Inter,ui-sans-serif,system-ui,sans-serif;background:#0b1220}.leaflet-popup-content-wrapper,.leaflet-popup-tip{background:#0d1320;color:#f8fafc}.leaflet-popup-content{font-size:12px;line-height:1.5}.leaflet-control-zoom a{background:#0d1320;color:#f8fafc;border-color:#334155}.charts{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:18px}.chart-wrap{height:280px}.chart-col{min-width:0}@media(max-width:1000px){.kpis{grid-template-columns:1fr 1fr}.layout-main{grid-template-columns:1fr}.map-wrap{height:360px}.charts{grid-template-columns:1fr}.projects{grid-template-columns:1fr}}@media(max-width:600px){.wrap{padding:16px}.title{font-size:25px}.project{min-height:195px;padding:18px}.pname{font-size:16px}.projects{gap:12px}}
    </style>
</head>
<body>
<div class="wrap">
    <header class="header"><div><div class="eyebrow">Tazaka Management</div><div class="title">Executive Project Monitor</div></div></header>
    <section class="kpis"><div class="kpi"><div class="kpi-label">TOTAL PROJECT</div><div class="kpi-value" id="total">0</div></div><div class="kpi"><div class="kpi-label">RUNNING</div><div class="kpi-value" id="running">0</div></div><div class="kpi"><div class="kpi-label">COMPLETED</div><div class="kpi-value" id="completed">0</div></div><div class="kpi"><div class="kpi-label">AVG PROGRESS</div><div class="kpi-value"><span id="average">0</span>%</div></div></section>

    <section class="layout-main">
        <div class="card project-card"><h2>Active Projects</h2><div id="projects" class="projects"></div></div>
        <div class="card map-card"><h2>Project Locations · Indonesia</h2><div class="map-wrap"><div id="projectMap" class="map"></div></div></div>
    </section>

    <section class="charts">
        <div class="card chart-col"><h2>Project Type</h2><div class="chart-wrap"><canvas id="projectTypeChart"></canvas></div></div>
        <div class="card chart-col"><h2>Overall Progress</h2><div class="chart-wrap"><canvas id="progressChart"></canvas></div></div>
    </section>
</div>
<script>
const initialProjects=@json($projects);let projectTypeChart,progressChart,projectMap,projectMarkers;
const chartColors=['#38bdf8','#a78bfa','#f59e0b','#34d399','#fb7185'];
const chartTextColor='#e2e8f0';
function typeLabel(t){return{tazaka_order:'Tazaka Order',subcontract:'Subcontract',external:'External'}[t]??t}
function escapeHtml(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function render(projects,summary=null){
    const s=summary??{total:projects.length,running:projects.filter(p=>Number(p.progress||0)<100).length,completed:projects.filter(p=>Number(p.progress||0)>=100).length,average_progress:projects.length?Math.round(projects.reduce((a,p)=>a+Number(p.progress||0),0)/projects.length):0};
    document.getElementById('total').textContent=s.total;document.getElementById('running').textContent=s.running;document.getElementById('completed').textContent=s.completed;document.getElementById('average').textContent=s.average_progress;
    if(typeof Chart==='undefined'){console.error('Chart.js gagal dimuat');return;}
    const types=['tazaka_order','subcontract','external'];const typeValues=types.map(t=>projects.filter(p=>p.project_type===t).length);
    if(projectTypeChart)projectTypeChart.destroy();
    projectTypeChart=new Chart(document.getElementById('projectTypeChart'),{type:'pie',data:{labels:types.map(typeLabel),datasets:[{data:typeValues,backgroundColor:chartColors,borderWidth:2,borderColor:'#0d1320'}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom',labels:{color:chartTextColor,padding:16,font:{size:12,weight:'600'}}}}}});
    const completed=projects.filter(p=>Number(p.progress||0)>=100).length,running=projects.length-completed;
    if(progressChart)progressChart.destroy();
    progressChart=new Chart(document.getElementById('progressChart'),{type:'doughnut',data:{labels:['Completed','In Progress'],datasets:[{data:[completed,running],backgroundColor:['#34d399','#38bdf8'],borderWidth:2,borderColor:'#0d1320'}]},options:{responsive:true,maintainAspectRatio:false,cutout:'72%',plugins:{legend:{position:'bottom',labels:{color:chartTextColor,padding:16,font:{size:12,weight:'600'}}}}}});
    const sorted=[...projects].sort((a,b)=>Number(b.progress)-Number(a.progress));document.getElementById('projects').innerHTML=sorted.length?sorted.map((p,i)=>`<article class="project"><div class="project-top"><div><div class="project-label">Tazaka Project</div><div class="pname">${escapeHtml(p.name)}</div><div class="client">${escapeHtml(p.client??'')}</div></div><span class="badge">${typeLabel(p.project_type)}</span></div><div class="project-middle"><div class="chip" aria-hidden="true"></div><div class="project-id">PROJECT <strong>#${escapeHtml(p.id??String(i+1).padStart(2,'0'))}</strong></div><div class="project-progress"><div class="progress-label"><span>Progress</span><strong>${Number(p.progress)}%</strong></div><div class="progress"><div class="bar" style="width:${Math.max(0,Math.min(100,Number(p.progress)||0))}%"></div></div></div></div><div class="project-bottom"><div><div class="project-bottom-label">Client</div><div class="project-bottom-value">${escapeHtml(p.client??'-')}</div></div><div style="text-align:right"><div class="project-bottom-label">Target Completion</div><div class="project-bottom-value">${escapeHtml(p.target_completion_date??'-')}</div></div></div></article>`).join(''):'<div class="muted">Belum ada project.</div>';
}
function initMap(){
    if(typeof L==='undefined'){console.error('Leaflet gagal dimuat');return;}
    projectMap=L.map('projectMap',{zoomControl:true,worldCopyJump:false}).setView([-2.5,118],5);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(projectMap);projectMarkers=L.layerGroup().addTo(projectMap);renderMap(initialProjects);
}
function renderMap(projects){if(!projectMap)return;projectMarkers.clearLayers();projects.forEach(p=>{const c=p.latlong,lat=Number(c?.lat),lng=Number(c?.lng);if(!Number.isFinite(lat)||!Number.isFinite(lng))return;const marker=L.marker([lat,lng]).addTo(projectMarkers);marker.bindPopup(`<strong>${escapeHtml(p.name)}</strong><br>${escapeHtml(p.client??'')}<br>Progress: ${Number(p.progress||0)}%<br>${escapeHtml(p.location??'')}`)});projectMap.setView([-2.5,118],5)}
render(initialProjects);initMap();setTimeout(()=>projectMap?.invalidateSize(),200);
</script>
</body></html>
